  const [myCartItems, setMyCartItems] = useState<any[]>(() => {
    try {
      const saved = localStorage.getItem('hanfarm_mypage_cart_items_v1');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) {
          return parsed.map((item: any) => {
            const safeThumb = resolveAgroProductThumbUrl(item);
            return {
              ...item,
              thumbnailUrl: safeThumb,
              thumbnail_url: safeThumb,
            };
          });
        }
      }
    } catch {
      // ignore
    }
    return defaultMyCartItems;
  });

  const saveMyCartItems = (updater: (prev: any[]) => any[]) => {
    setMyCartItems((prev) => {
      const next = updater(prev);
      try {
        localStorage.setItem(MYPAGE_CART_STORAGE_KEY, JSON.stringify(next));
      } catch {
        // ignore
      }
      fetch('/api/client-sync-state', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: loggedInUser.email || 'CloudBae@naver.com',
          state_key: 'mypage_cart_items_v1',
          state_value: next,
        }),
      }).catch(() => {});
      return next;
    });
  };

  const handleToggleCartItem = (cartId: string) => {
    saveMyCartItems((prev) =>
      prev.map((it) => (it.cartId === cartId ? { ...it, checked: !it.checked } : it))
    );
  };

  const handleToggleAllCartItems = (checked: boolean) => {
    saveMyCartItems((prev) => prev.map((it) => ({ ...it, checked })));
  };

  const handleChangeCartItemQty = (cartId: string, nextOrDelta: number, isDelta = false) => {
    saveMyCartItems((prev) =>
      prev.map((it) => {
        if (it.cartId !== cartId) return it;
        const cur = Math.max(1, Number(it.qty) || 1);
        const target = isDelta ? cur + nextOrDelta : nextOrDelta;
        return { ...it, qty: Math.max(1, Math.min(99, Number(target) || 1)) };
      })
    );
  };

  const handleRemoveCartItem = (cartId: string) => {
    saveMyCartItems((prev) => prev.filter((it) => it.cartId !== cartId));
    setMyPageToast('선택한 장바구니 품목이 삭제되었습니다.');
    setTimeout(() => setMyPageToast(''), 3000);
  };

  const handleRemoveSelectedCartItems = () => {
    const selectedCount = myCartItems.filter((it) => it.checked).length;
    if (selectedCount === 0) return;
    saveMyCartItems((prev) => prev.filter((it) => !it.checked));
    setMyPageToast(`선택한 장바구니 품목 ${selectedCount}건이 삭제되었습니다.`);
    setTimeout(() => setMyPageToast(''), 3000);
  };

  const handleResetSampleCartItems = () => {
    saveMyCartItems(() => defaultMyCartItems);
    setMyPageToast('생육단계별 맞춤 샘플 장바구니 품목 4건이 다시 담겼습니다.');
    setTimeout(() => setMyPageToast(''), 3000);
  };

  const handleCheckoutCartItems = (targetCartIds?: string[]) => {
    const isSingleDirect = Array.isArray(targetCartIds) && targetCartIds.length > 0;
    const itemsToBuy = isSingleDirect
      ? myCartItems.filter((it) => targetCartIds.includes(it.cartId))
      : myCartItems.filter((it) => it.checked);

    if (itemsToBuy.length === 0) {
      setMyPageToast('구매할 장바구니 품목을 먼저 선택해 주세요.');
      setTimeout(() => setMyPageToast(''), 3000);
      return;
    }

    const now = new Date();
    const datePart = `${now.getFullYear()}${String(now.getMonth() + 1).padStart(2, '0')}${String(
      now.getDate()
    ).padStart(2, '0')}`;
    const orderedAt = `${now.getFullYear()}.${String(now.getMonth() + 1).padStart(
      2,
      '0'
    )}.${String(now.getDate()).padStart(2, '0')} ${String(now.getHours()).padStart(
      2,
      '0'
    )}:${String(now.getMinutes()).padStart(2, '0')}`;

    const newPurchases = itemsToBuy.map((it, idx) => {
      const safeQty = Math.max(1, Number(it.qty) || 1);
      const unitPrice = Number(it.unitPrice || 18000);
      const rawSubtotal = unitPrice * safeQty;
      const discountAmount = Math.round((rawSubtotal * 0.05) / 10) * 10;
      const finalSubtotal = Math.max(0, rawSubtotal - discountAmount);
      const orderNo = `ORD-${datePart}-CRT${String(Math.floor(100 + Math.random() * 900))}`;
      const entryId = `SPUR-CRT-${Date.now()}-${idx}`;
      const thumbUrl = resolveAgroProductThumbUrl(it);

      return {
        id: entryId,
        purchase_id: entryId,
        cartId: it.cartId,
        orderNo,
        order_no: orderNo,
        purchasedAt: orderedAt,
        ordered_at: orderedAt,
        requestNo: it.requestNo || 'REQ-20261106-009',
        request_no: it.requestNo || 'REQ-20261106-009',
        display_request_no: it.requestNo || 'REQ-20261106-009',
        cropTitle: it.cropTitle || '가을배추 (불암3호)',
        crop_title: it.cropTitle || '가을배추 (불암3호)',
        cropCategory: it.cropCategory || '엽채류',
        plantingType: it.plantingType || '모종',
        planting_type: it.plantingType || '모종',
        region: it.region || '충청북도 충주시 단월동',
        region_address: `${it.region || '충청북도 충주시 단월동'} (${
          loggedInUser.name || '배철민'
        } 농장)`,
        areaPyeong: Number(it.areaPyeong || 300),
        area_pyeong: Number(it.areaPyeong || 300),
        plantingDate: it.plantingDate || '2026-08-25',
        planting_date: it.plantingDate || '2026-08-25',
        expectedHarvestDate: it.expectedHarvestDate || '2026-11-15',
        expected_harvest_date: it.expectedHarvestDate || '2026-11-15',
        stageGroupName: it.stageGroupName || '04. 생육 관리',
        stage_group_name: it.stageGroupName || '04. 생육 관리',
        stageColor: it.stageColor || '#16a34a',
        stage_color: it.stageColor || '#16a34a',
        stageItemId: it.processCode || 'SCH-09',
        item_id: it.processCode || 'SCH-09',
        processCode: it.processCode || 'SCH-09',
        process_code: it.processCode || 'SCH-09',
        subItemName: it.subItemName || '생육과정',
        sub_item_name: it.subItemName || '생육과정',
        processName: it.processName || it.subItemName || '생육과정',
        process_name: it.processName || it.subItemName || '생육과정',
        startDate: it.startDate || '2026-09-10',
        recommended_date: it.startDate || '2026-09-10',
        startWeekLabel: it.startWeekLabel || '',
        targetPgdd: Number(it.targetPgdd || 0),
        target_pgdd: Number(it.targetPgdd || 0),
        workDescription: it.workDescription || '',
        work_content: it.workDescription || '',
        material_id: it.material_id || 'FERT-PRD-01',
        material_category: it.material_category || 'FERTILIZER',
        subType: it.subType || it.categoryName || '맞춤 농자재',
        sub_type: it.subType || it.categoryName || '맞춤 농자재',
        manufacturer: it.manufacturer || it.brandName || '한팜인증',
        productName: it.productName || '생육과정 추천 농자재',
        product_name: it.productName || '생육과정 추천 농자재',
        unitSpec: it.unitSpec || it.spec || '1개',
        unit_spec: it.unitSpec || it.spec || '1개',
        unitLabel: it.unitLabel || '개',
        unit_label: it.unitLabel || '개',
        unitPrice,
        unit_price: unitPrice,
        qty: safeQty,
        recommendedQty: Number(it.recommendedQty || safeQty),
        raw_subtotal: rawSubtotal,
        discount_amount: discountAmount,
        totalPrice: finalSubtotal,
        final_subtotal: finalSubtotal,
        matchScore: Number(it.matchScore || 96),
        match_score: Number(it.matchScore || 96),
        categorySpecBadge: it.categorySpecBadge || it.usageNote || '',
        spec_summary: it.categorySpecBadge || it.usageNote || '',
        thumbnailUrl: thumbUrl,
        thumbnail_url: thumbUrl,
        deliveryStatus: '구매완료 · 장바구니 주문 적기 배송예약',
        delivery_status: '구매완료 · 장바구니 주문 적기 배송예약',
        payment_method_label: '기본 입금계좌 무통장입금 (5% 회원할인)',
      };
    });

    refreshPrimaryBankAccount();
    setBankAccountCopied(false);
    setCheckoutConfirmPageData({
      mode: isSingleDirect ? 'DIRECT_BUY' : 'SELECTED_PRODUCTS',
      triggerLabel: isSingleDirect ? '바로 구매' : '선택제품 구매',
      items: newPurchases,
      cartIdsToRemove: itemsToBuy.map((it) => it.cartId),
      isCompleted: false,
    });
  };

  const handleChangeCheckoutConfirmItemQty = (idx: number, nextQtyOrDelta: number, isDelta = false) => {
    setCheckoutConfirmPageData((prev) => {
      if (!prev || prev.isCompleted) return prev;
      const nextItems = prev.items.map((entry, i) => {
        if (i !== idx) return entry;
        const curQty = Math.max(1, Number(entry.qty) || 1);
        const target = isDelta ? curQty + nextQtyOrDelta : nextQtyOrDelta;
        const safeQty = Math.max(1, Math.min(999, Number(target) || 1));
        const unitPrice = Number(entry.unitPrice ?? entry.unit_price ?? 18000);
        const rawSubtotal = unitPrice * safeQty;
        const discountAmount = Math.round((rawSubtotal * 0.05) / 10) * 10;
        const finalSubtotal = Math.max(0, rawSubtotal - discountAmount);
        return {
          ...entry,
          qty: safeQty,
          raw_subtotal: rawSubtotal,
          discount_amount: discountAmount,
          totalPrice: finalSubtotal,
          final_subtotal: finalSubtotal,
        };
      });
      return { ...prev, items: nextItems };
    });
  };

  const resolveAgroCategory1stLabel = (rawCat?: any, rawSub?: string, rawName?: string): string => {
    if (rawCat && typeof rawCat === 'object') {
      return resolveAgroCategory1stLabel(
        rawCat.material_category || rawCat.category_1st,
        rawCat.subType || rawCat.sub_type || rawCat.categoryName,
        rawCat.productName || rawCat.product_name
      );
    }
    const c = String(rawCat || '').toUpperCase().trim();
    if (c === 'FERTILIZER' || c.includes('비료')) return '비료';
    if (c === 'NUTRIENT' || c.includes('영양')) return '영양제';
    if (c === 'PESTICIDE' || c.includes('병해충') || c.includes('살균') || c.includes('살충') || c.includes('제초'))
      return '병해충관리제';
    if (c === 'SEED' || c === '씨' || c.includes('종자')) return '씨';
    if (c === 'SEEDLING' || c === '모종' || c.includes('육묘')) return '모종';
    const subAndName = `${rawSub || ''} ${rawName || ''}`;
    if (subAndName.includes('영양') || subAndName.includes('칼슘') || subAndName.includes('붕소') || subAndName.includes('발근'))
      return '영양제';
    if (subAndName.includes('살균') || subAndName.includes('살충') || subAndName.includes('제초') || subAndName.includes('방제'))
      return '병해충관리제';
    if (subAndName.includes('종자') || subAndName.includes('씨앗')) return '씨';
    if (subAndName.includes('모종') || subAndName.includes('프러그묘') || subAndName.includes('접목묘')) return '모종';
    return '비료';
  };

  const handleFinalizeConfirmedPurchase = () => {
    if (!checkoutConfirmPageData || checkoutConfirmPageData.items.length === 0) return;
    const memberEmail = loggedInUser.email || 'CloudBae@naver.com';
    const memberName = loggedInUser.name || '배철민';

    const confirmedItems = checkoutConfirmPageData.items.map((item) => {
      const cat1st = resolveAgroCategory1stLabel(
        item.material_category,
        item.subType || item.sub_type,
        item.productName || item.product_name
      );
      const cat2nd = String(item.subType || item.sub_type || `${cat1st} 일반`).trim();
      return {
        ...item,
        member_id: memberEmail,
        email: memberEmail,
        member_name: memberName,
        category_1st: cat1st,
        category_2nd: cat2nd,
        bank_name: primaryBankAccount.bank_name || 'NH농협은행',
        account_number: primaryBankAccount.account_number || '301-0348-9120-81',
        account_holder: primaryBankAccount.account_holder || '(주)한팜',
        payment_method_label: `${primaryBankAccount.bank_name || 'NH농협은행'} ${
          primaryBankAccount.account_number || '301-0348-9120-81'
        } (${primaryBankAccount.account_holder || '(주)한팜'})`,
      };
    });

    setStagePurchaseHistory((prev) => {
      const updated = [...confirmedItems, ...prev];
      try {
        localStorage.setItem(STAGE_PURCHASE_STORAGE_KEY, JSON.stringify(updated));
      } catch {
        // ignore
      }
      try {
        const existingSalesRaw = localStorage.getItem('hanfarm_admin_agro_sales_v1');
        const existingSales = existingSalesRaw ? JSON.parse(existingSalesRaw) : [];
        const safeSales = Array.isArray(existingSales) ? existingSales : [];
        const newIds = new Set(confirmedItems.map((ci) => ci.id || ci.purchase_id));
        const mergedSales = [
          ...confirmedItems,
          ...safeSales.filter((s: any) => !newIds.has(s.id || s.purchase_id)),
        ];
        localStorage.setItem('hanfarm_admin_agro_sales_v1', JSON.stringify(mergedSales));
      } catch {
        // ignore
      }
      fetch('/api/client-sync-state', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: memberEmail,
          state_key: 'stage_purchase_history_v1',
          state_value: updated,
        }),
      }).catch(() => {});
      return updated;
    });

    if (checkoutConfirmPageData.cartIdsToRemove.length > 0) {
      const boughtIdSet = new Set(checkoutConfirmPageData.cartIdsToRemove);
      saveMyCartItems((prev) => prev.filter((it) => !boughtIdSet.has(it.cartId)));
    }

    if (checkoutConfirmPageData.stageNoticePayload) {
      const first = confirmedItems[0];
      if (first) {
        setStageDetailPurchaseNotice({
          ...checkoutConfirmPageData.stageNoticePayload,
          qty: first.qty,
          finalAmount: first.totalPrice,
          message: `${first.productName} ${first.qty}${first.unitLabel || '개'} (${Number(
            first.totalPrice || 0
          ).toLocaleString()}원) 구매가 완료되었습니다.`,
        });
      }
    }

    const totalRaw = confirmedItems.reduce((s, p) => s + Number(p.raw_subtotal || 0), 0);
    const totalDisc = confirmedItems.reduce((s, p) => s + Number(p.discount_amount || 0), 0);
    const totalPaid = confirmedItems.reduce((s, p) => s + Number(p.totalPrice || 0), 0);
    const firstItem = confirmedItems[0] || {};

    fetch('/api/mypage/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: memberEmail,
        orderNo: firstItem.orderNo || `ORD-${Date.now()}`,
        orderedAt: firstItem.purchasedAt || '',
        purchaseTitle:
          confirmedItems.length > 1
            ? `${firstItem.productName} 외 ${confirmedItems.length - 1}건 (${checkoutConfirmPageData.triggerLabel})`
            : `${firstItem.productName} (${checkoutConfirmPageData.triggerLabel})`,
        cropTitle: `${firstItem.cropTitle || '가을배추 (불암3호)'}`,
        regionAddress: firstItem.region_address || '',
        deliveryOption: 'STAGE_SCHEDULED',
        paymentMethod: 'BANK_TRANSFER',
        bankAccount: primaryBankAccount,
        orderRawTotal: totalRaw,
        orderDiscount: totalDisc,
        orderFinalTotal: totalPaid,
        rewardPoints: Math.round(totalPaid * 0.02),
        orderItems: confirmedItems.map((ci) => ({
          stageName: `${ci.stageGroupName || '생육 관리'} (${ci.subItemName || '생육과정'})`,
          process_code: ci.processCode || 'SCH-01',
          sub_item_name: ci.subItemName || '생육과정',
          recommended_date: ci.startDate || '2026-08-25',
          material_id: ci.material_id,
          material_category: ci.material_category,
          category_1st: ci.category_1st,
          category_2nd: ci.category_2nd,
          product_name: ci.productName,
          unit_spec: ci.unitSpec,
          unit_price: ci.unitPrice,
          qty: ci.qty,
          subtotal: ci.raw_subtotal,
          scheduledDeliveryDate: addDaysToYmd(ci.startDate || '2026-08-25', -3),
          thumbnail_url: ci.thumbnailUrl,
        })),
      }),
    })
      .then((r) => r.json())
      .then((res) => {
        if (res?.ok) applyMyPagePayload(res);
      })
      .catch(() => {});

    const nowDt = new Date();
    const nextDayDt = new Date(nowDt.getTime() + 86400000);
    const wkNames = ['일', '월', '화', '수', '목', '금', '토'];
    const orderedAtDisplay =
      firstItem.purchasedAt ||
      `${nowDt.getFullYear()}.${String(nowDt.getMonth() + 1).padStart(2, '0')}.${String(
        nowDt.getDate()
      ).padStart(2, '0')} ${String(nowDt.getHours()).padStart(2, '0')}:${String(
        nowDt.getMinutes()
      ).padStart(2, '0')}`;
    const deliveryExpectedDisplay = `${nextDayDt.getFullYear()}.${String(
      nextDayDt.getMonth() + 1
    ).padStart(2, '0')}.${String(nextDayDt.getDate()).padStart(2, '0')} (${
      wkNames[nextDayDt.getDay()]
    })`;
    const orderNoDisplay = String(firstItem.orderNo || `HF-${Date.now()}`)
      .replace(/^ORD-/, 'HF-')
      .replace(/-CART|-DIR|-STG/g, '-');
    const deliveryAddrDisplay =
      firstItem.region_address ||
      firstItem.region ||
      loggedInUser.road_address ||
      '충북 충주시 봉방동';

    setCheckoutConfirmPageData((prev) =>
      prev
        ? {
            ...prev,
            isCompleted: true,
            completedReceipt: {
              orderNo: orderNoDisplay,
              orderedAt: orderedAtDisplay,
              expectedDeliveryDate: deliveryExpectedDisplay,
              deliveryAddress: deliveryAddrDisplay,
              itemCount: confirmedItems.length,
              totalPaid,
            },
          }
        : null
    );
    setMyPageToast(
      `선택하신 제품 ${confirmedItems.length}건 (총 ${totalPaid.toLocaleString()}원) 주문이 완료되었습니다.`
    );
    setTimeout(() => setMyPageToast(''), 4500);
  };

  const defaultStagePurchases = useMemo<any[]>(() => [], []);

  const [stagePurchaseHistory, setStagePurchaseHistory] = useState<any[]>(() => {
    try {
      const saved = localStorage.getItem('hanfarm_stage_purchase_history_v1');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed)) {
          const repaired = parsed.map((item: any) => {
            const safeThumb = resolveAgroProductThumbUrl(item);
            return {
              ...item,
              thumbnailUrl: safeThumb,
              thumbnail_url: safeThumb,
            };
          });
          localStorage.setItem('hanfarm_stage_purchase_history_v1', JSON.stringify(repaired));
          return repaired;
        }
      }
    } catch {
      // ignore
    }
    return defaultStagePurchases;
  });

  const handleDeleteStagePurchaseItem = async (entryOrId: any, targetIndex?: number) => {
    if (entryOrId === null || entryOrId === undefined) return;
    const isStringId = typeof entryOrId === 'string';
    const entry = isStringId
      ? stagePurchaseHistory.find(
          (p: any, i: number) =>
            (p.id || p.purchase_id || `SPUR-ROW-${i}`) === entryOrId ||
            `agro-purchase-${i}` === entryOrId ||
            (p.orderNo || p.order_no) === entryOrId
        ) || { id: entryOrId }
      : entryOrId;

    const productName = entry.productName || entry.product_name || '농자재 상품';
    const orderNo = entry.orderNo || entry.order_no || '';
    if (
      !window.confirm(
        `[${productName}${orderNo ? ` · ${orderNo}` : ''}] 농자재 구매 내역을 삭제하시겠습니까?`
      )
    ) {
      return;
    }

    const targetId = isStringId ? entryOrId : entry.id || entry.purchase_id || '';
    setStagePurchaseHistory((prev) => {
      const updated = prev.filter((p: any, idx: number) => {
        if (typeof targetIndex === 'number' && idx === targetIndex) {
          return false;
        }
        if (!isStringId && p === entry) {
          return false;
        }
        const pId = p.id || p.purchase_id || `SPUR-ROW-${idx}`;
        if (targetId && (pId === targetId || `agro-purchase-${idx}` === targetId)) return false;
        if (
          orderNo &&
          (p.orderNo || p.order_no) === orderNo &&
          (p.material_id || p.productName || p.product_name) ===
            (entry.material_id || entry.productName || entry.product_name) &&
          (p.stageItemId || p.item_id || p.processCode || p.process_code) ===
            (entry.stageItemId || entry.item_id || entry.processCode || entry.process_code)
        ) {
          return false;
        }
        return true;
      });
      try {
        localStorage.setItem(STAGE_PURCHASE_STORAGE_KEY, JSON.stringify(updated));
        const existingSalesRaw = localStorage.getItem('hanfarm_admin_agro_sales_v1');
        if (existingSalesRaw) {
          const parsedSales = JSON.parse(existingSalesRaw);
          if (Array.isArray(parsedSales)) {
            const filteredSales = parsedSales.filter(
              (s: any) =>
                (targetId ? (s.id || s.purchase_id) !== targetId : true) &&
                (orderNo ? (s.orderNo || s.order_no) !== orderNo : true)
            );
            localStorage.setItem('hanfarm_admin_agro_sales_v1', JSON.stringify(filteredSales));
          }
        }
      } catch {
        // ignore
      }
      fetch('/api/client-sync-state', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: loggedInUser.email || 'CloudBae@naver.com',
          state_key: 'stage_purchase_history_v1',
          state_value: updated,
        }),
      }).catch(() => {});
      return updated;
    });

    if (orderNo) {
      setMyOrders((prev) => prev.filter((o: any) => (o.order_no || o.orderNo) !== orderNo));
      fetch('/api/mypage/orders/delete', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          email: loggedInUser.email || 'CloudBae@naver.com',
          order_no: orderNo,
        }),
      }).catch(() => {});
    }

    setMyPageToast(`[${productName}] 농자재 구매 내역이 삭제되었습니다.`);
    setTimeout(() => setMyPageToast(''), 3500);
  };

  const handleDeleteAllStagePurchases = async () => {
    if (stagePurchaseHistory.length === 0) return;
    if (
      !window.confirm(
        `농자재 구매 내역(${stagePurchaseHistory.length}건)을 모두 삭제하시겠습니까?`
      )
    ) {
      return;
    }

    setStagePurchaseHistory([]);
    setMyOrders([]);
    setMyPagePurchaseCropFilter('ALL');
    try {
      localStorage.setItem(STAGE_PURCHASE_STORAGE_KEY, JSON.stringify([]));
    } catch {
      // ignore
    }
    fetch('/api/client-sync-state', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: loggedInUser.email || 'CloudBae@naver.com',
        state_key: 'stage_purchase_history_v1',
        state_value: [],
      }),
    }).catch(() => {});

    fetch('/api/mypage/orders/delete', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        email: loggedInUser.email || 'CloudBae@naver.com',
        delete_all: true,
      }),
    }).catch(() => {});

    setMyPageToast('농자재 구매 내역이 모두 삭제되었습니다.');
    setTimeout(() => setMyPageToast(''), 3500);
  };

  // provisionData가 로드되면 초기 시드 항목(SPUR-INIT-01, SPUR-INIT-02)의 공정명·제품명을 실제 생육과정 데이터와 자동 정합화
  useEffect(() => {
    if (!provisionData?.scheduleItems?.length) return;
    const activeReqNo = provisionData?.activeRequest?.request_no || selectedRequestNo || 'REQ-20261106-009';
    if (activeReqNo !== 'REQ-20261106-009') return;

    setStagePurchaseHistory((prev) => {
      let changed = false;
      const next = prev.map((entry) => {
        const currentSafeThumb = resolveAgroProductThumbUrl(entry);
        const thumbNeedsRepair =
          entry.thumbnailUrl !== currentSafeThumb || entry.thumbnail_url !== currentSafeThumb;

        if (entry.purchase_id !== 'SPUR-INIT-01' && entry.purchase_id !== 'SPUR-INIT-02') {
          if (thumbNeedsRepair) {
            changed = true;
            return {
              ...entry,
              thumbnailUrl: currentSafeThumb,
              thumbnail_url: currentSafeThumb,
            };
          }
          return entry;
        }
        const matchedItem = (provisionData.scheduleItems || []).find(
          (it: any) =>
            it.process_code === entry.process_code || it.item_id === entry.item_id
        );
        if (!matchedItem) {
          if (thumbNeedsRepair) {
            changed = true;
            return {
              ...entry,
              thumbnailUrl: currentSafeThumb,
              thumbnail_url: currentSafeThumb,
            };
          }
          return entry;
        }
        const topMat = [...(matchedItem.materials || [])].sort(
          (a: any, b: any) => Number(b?.match_score || 0) - Number(a?.match_score || 0)
        )[0];
        if (!topMat) return entry;

        const unitSpec = String(topMat.unit_spec || entry.unit_spec || '1개');
        const unitMatch = unitSpec.match(/(포|병|봉|통|팩|판|박스|개|롤)/);
        const unitLabel = topMat.unit_label || (unitMatch ? unitMatch[1] : entry.unit_label || '개');
        const unitPrice = Number(topMat.unit_price || entry.unit_price || 18000);
        const rawSub = unitPrice * Number(entry.qty || 1);
        const disc = Math.round((rawSub * 0.05) / 10) * 10;
        const finalSub = Math.max(0, rawSub - disc);
        const cleanSub = String(matchedItem.sub_item_name || entry.sub_item_name || '')
          .replace(/\s*\([^)]*\)/g, '')
          .trim();
        const resolvedTopThumb = resolveAgroProductThumbUrl(topMat);

        if (
          entry.product_name !== topMat.product_name ||
          entry.item_id !== matchedItem.item_id ||
          entry.thumbnailUrl !== resolvedTopThumb ||
          entry.thumbnail_url !== resolvedTopThumb
        ) {
          changed = true;
          return {
            ...entry,
            stage_group_name: matchedItem.stage_group_name || entry.stage_group_name,
            item_id: matchedItem.item_id || entry.item_id,
            process_code: matchedItem.process_code || entry.process_code,
            sub_item_name: cleanSub || entry.sub_item_name,
            process_name: matchedItem.process_name || matchedItem.sub_item_name || entry.process_name,
            recommended_date: matchedItem.start_date || entry.recommended_date,
            target_pgdd: Number(matchedItem.target_pgdd ?? entry.target_pgdd ?? 0),
            work_content:
              matchedItem.work_content || matchedItem.work_description || entry.work_content,
            material_id: topMat.material_id || entry.material_id,
            material_category: topMat.material_category || entry.material_category,
            sub_type: topMat.sub_type || entry.sub_type,
            manufacturer: topMat.manufacturer || entry.manufacturer,
            product_name: topMat.product_name || entry.product_name,
            unit_spec: unitSpec,
            unit_label: unitLabel,
            unit_price: unitPrice,
            raw_subtotal: rawSub,
            discount_amount: disc,
            final_subtotal: finalSub,
            match_score: Number(topMat.match_score || entry.match_score || 96),
            spec_summary:
              topMat.category_spec_badge ||
              topMat.nutrient_ratio_summary ||
              entry.spec_summary,
            thumbnailUrl: resolvedTopThumb,
            thumbnail_url: resolvedTopThumb,
          };
        }
        return entry;
      });
      if (changed) {
        try {
          localStorage.setItem(STAGE_PURCHASE_STORAGE_KEY, JSON.stringify(next));
        } catch {
          // ignore
        }
      }
      return changed ? next : prev;
    });
  }, [provisionData, selectedRequestNo]);

  const getStageRecQtyKey = (reqNo: string, stageItem: any, mat: any): string => {
    const rNo = reqNo || provisionData?.activeRequest?.request_no || selectedRequestNo || 'REQ-20261106-009';
    const stgCode = stageItem?.item_id || stageItem?.process_code || stageItem?.sub_item_name || 'STG';
    const matCode = mat?.material_id || mat?.product_name || 'MAT';
    return `${rNo}__${stgCode}__${matCode}`;
  };

  const getStageRecQty = (reqNo: string, stageItem: any, mat: any, defaultQty: number): number => {
    const key = getStageRecQtyKey(reqNo, stageItem, mat);
    const val = stageDetailQtyMap[key];
    return typeof val === 'number' && val >= 1 ? val : Math.max(1, Number(defaultQty) || 1);
  };

  const handleSetStageRecQty = (
    reqNo: string,
    stageItem: any,
    mat: any,
    defaultQty: number,
    nextQtyOrDelta: number,
    isDelta = false
  ) => {
    const key = getStageRecQtyKey(reqNo, stageItem, mat);
    setStageDetailQtyMap((prev) => {
      const cur = typeof prev[key] === 'number' && prev[key] >= 1 ? prev[key] : Math.max(1, Number(defaultQty) || 1);
      const target = isDelta ? cur + nextQtyOrDelta : nextQtyOrDelta;
      const clamped = Math.max(1, Math.min(99, Number(target) || 1));
      return { ...prev, [key]: clamped };
    });
  };

  const getPurchasedStageProductInfo = (reqNo: string, stageItem: any, mat: any) => {
    const targetReqNo =
      reqNo || provisionData?.activeRequest?.request_no || selectedRequestNo || 'REQ-20261106-009';
    const targetProcessCode = String(stageItem?.process_code || '').trim();
    const targetItemId = String(stageItem?.item_id || '').trim();
    const targetSubName = String(stageItem?.sub_item_name || '')
      .replace(/\s*\([^)]*\)/g, '')
      .trim();
    const targetMatId = String(mat?.material_id || mat?.materialId || '').trim();
    const targetProdName = String(mat?.product_name || mat?.productName || '').trim();
    const subProcessList: any[] = Array.isArray(mat?.subProcesses) ? mat.subProcesses : [];

    const matchedEntries = stagePurchaseHistory.filter((entry: any) => {
      const entryReqNo = String(
        entry.request_no || entry.requestNo || entry.display_request_no || ''
      ).trim();
      const reqMatch = !entryReqNo || entryReqNo === targetReqNo;
      if (!reqMatch) return false;

      const entryProcessCode = String(entry.process_code || entry.processCode || '').trim();
      const entryItemId = String(entry.item_id || entry.stageItemId || '').trim();
      const entrySubName = String(entry.sub_item_name || entry.subItemName || '')
        .replace(/\s*\([^)]*\)/g, '')
        .trim();
      const entryMatId = String(entry.material_id || entry.materialId || '').trim();
      const entryProdName = String(entry.product_name || entry.productName || '').trim();

      const prodMatch =
        (targetMatId && entryMatId === targetMatId) ||
        (targetProdName && entryProdName === targetProdName);

      if (prodMatch) {
        return true;
      }

      const stageMatch =
        (targetProcessCode && entryProcessCode === targetProcessCode) ||
        (targetItemId && entryItemId === targetItemId) ||
        (targetSubName &&
          (entrySubName === targetSubName ||
            entrySubName.includes(targetSubName) ||
            targetSubName.includes(entrySubName))) ||
        subProcessList.some((sp) => {
          const spId = String(sp?.item_id || '').trim();
          const spCode = String(sp?.process_code || '').trim();
          const spName = String(sp?.name || '').trim();
          return (
            (spId && entryItemId === spId) ||
            (spCode && entryProcessCode === spCode) ||
            (spName && (entrySubName === spName || entrySubName.includes(spName)))
          );
        });

      if (targetProcessCode || targetItemId) {
        return stageMatch && (prodMatch || !targetProdName);
      }
      return false;
    });

    const totalQty = matchedEntries.reduce((sum, e: any) => sum + Number(e.qty || 0), 0);
    return {
      isPurchased: matchedEntries.length > 0,
      totalQty,
      purchaseCount: matchedEntries.length,
      lastEntry: matchedEntries[0] || null,
      entries: matchedEntries,
    };
  };

